def retry(times):
    def deco(f):
        def w(*a, **k):
            for i in range(times):
                try:
                    return f(*a, **k)
                except Exception:
                    if i == times - 1:
                        raise
        return w
    return deco

state = {'n': 0}

@retry(3)
def flaky():
    state['n'] += 1
    if state['n'] < 3:
        raise ValueError
    return 'ok'

